Repair the complete CommonJS source below. Return a corrected complete source file exporting exactly `{ compareVersions }`.

`compareVersions(left, right)` compares dotted numeric version strings. Each input must be a nonempty string of one or more decimal-digit segments separated by single dots. Empty segments, signs, whitespace, and segments exceeding `Number.MAX_SAFE_INTEGER` are malformed and must throw `TypeError`. Leading zeroes are allowed. Missing trailing segments are treated as zero, so `"2.4"` equals `"2.4.0"`. Return `-1`, `0`, or `1` according to numeric ordering. Inputs must not be modified.

Known-bad source:
```javascript
'use strict';

function compareVersions(left, right) {
  const a = parseVersion(left);
  const b = parseVersion(right);
  const length = Math.max(a.length, b.length);

  for (let i = 0; i < length; i += 1) {
    const x = i < a.length ? a[i] : 0;
    const y = i < b.length ? b[i] : 0;
    if (x < y) return 1;
    if (x > y) return 1;
  }
  return 0;
}

function parseVersion(value) {
  if (typeof value !== 'string' || value.length === 0 || !/^\d+(?:\.\d+)*$/.test(value)) {
    throw new TypeError('invalid version');
  }
  return value.split('.').map(segment => {
    const number = Number(segment);
    if (!Number.isSafeInteger(number)) throw new TypeError('version segment is too large');
    return number;
  });
}

module.exports = { compareVersions };
```

