'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['compareVersions']);
const { compareVersions } = api;

assert.equal(compareVersions('1.2.3', '1.2.3'), 0);
assert.equal(compareVersions('2.4', '2.4.0'), 0);
assert.equal(compareVersions('2.4.0.0', '2.4'), 0);
assert.equal(compareVersions('1.2.3', '1.2.4'), -1);
assert.equal(compareVersions('1.10', '1.2'), 1);
assert.equal(compareVersions('3', '2.999.999'), 1);
assert.equal(compareVersions('0.0.1', '0.0.0.9'), 1);
assert.equal(compareVersions('0002.004', '2.4.0'), 0);
assert.equal(compareVersions(String(Number.MAX_SAFE_INTEGER), '1'), 1);
assert.equal(compareVersions('1', String(Number.MAX_SAFE_INTEGER)), -1);
assert.ok([-1, 0, 1].includes(compareVersions('1', '2')));

for (const bad of [
  '', '.', '1.', '.1', '1..2', ' 1.2', '1.2 ', '1 2',
  '+1', '-1', '1.-2', '1.a', 'v1.2', null, undefined, 123,
  String(Number.MAX_SAFE_INTEGER) + '0',
  '1.' + String(Number.MAX_SAFE_INTEGER) + '0'
]) {
  assert.throws(() => compareVersions(bad, '1'), TypeError);
  assert.throws(() => compareVersions('1', bad), TypeError);
}

const left = '001.02.0003';
const right = '1.2.3.0';
compareVersions(left, right);
assert.equal(left, '001.02.0003');
assert.equal(right, '1.2.3.0');

